+    
+    if (message) {
+        messageElement.textContent = message;
+        fieldInput.classList.remove('success');
+        fieldInput.classList.add('error');
+        return false;
+    } else {
+        messageElement.textContent = '';
+        fieldInput.classList.remove('error');
+        fieldInput.classList.add('success');
+        return true;
+    }
